        # If lengths are different, they can't be anagrams
        if len(s) != len(t):
            return False

        # Count character frequencies using a dictionary
        char_count = {}
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1

        for char in t:
            if char not in char_count:
                return False
            char_count[char] -= 1
            if char_count[char] < 0:
                return False

        return True
```

